changeSet.sql:
create or alter PROCEDURE [dbo].[UpdateDependentObjectTypeDisplayValues] @ChangedObject varchar(20), @ChangedObjectTypeID int AS BEGIN SET NOCOUNT ON;
Declare @ObjectType varchar(20); Declare @ObjectID int; Declare @AssetTypeID int;
SELECT @ChangedObject = REPLACE(@ChangedObject, 'Type', '');
if exists (select 1 from FieldType where LookupObjectType = @ChangedObject and LookupObjectID = @ChangedObjectTypeID) begin Print 'Found dependent lookup fields updating them'
Declare curP cursor LOCAL For
select distinct [Object] as ObjectType, ObjectID, AssetTypeID from FieldType where LookupObjectType = @ChangedObject and LookupObjectID = @ChangedObjectTypeID and AssetTypeID is not null
OPEN curP Fetch Next From curP Into @ObjectType, @ObjectID,@AssetTypeID
While @@Fetch_Status = 0 Begin print 'Updating dependent AssetTypeID' print @AssetTypeID exec GenerateAssetTypeDisplayValues @AssetTypeID Fetch Next From curP Into @ObjectType, @ObjectID,@AssetTypeID End
Close curP Deallocate curP end END
